replacement="""  Future<Position?> currentPosition() async {\n    try{\n      if(!await Geolocator.isLocationServiceEnabled())return null;\n      var permission=await Geolocator.checkPermission();\n      if(permission==LocationPermission.denied)permission=await Geolocator.requestPermission();\n      if(permission==LocationPermission.denied||permission==LocationPermission.deniedForever)return null;\n      Position? best;\n      final deadline=DateTime.now().add(const Duration(seconds:20));\n      while(DateTime.now().isBefore(deadline)){\n        final remaining=deadline.difference(DateTime.now());\n        if(remaining<=Duration.zero)break;\n        final slice=remaining>const Duration(seconds:5)?const Duration(seconds:5):remaining;\n        try{\n          final p=await Geolocator.getCurrentPosition(locationSettings:LocationSettings(accuracy:LocationAccuracy.bestForNavigation,timeLimit:slice));\n          if(best==null||p.accuracy<best.accuracy)best=p;\n          if(p.accuracy<=20)return p;\n        }catch(_){}\n        if(DateTime.now().isBefore(deadline))await Future<void>.delayed(const Duration(milliseconds:500));\n      }\n      return best!=null&&best.accuracy<=20?best:null;\n    }catch(_){return null;}\n  }\n\n"""
